// Menyusun kalimat yang dibaca orang, bukan JSON mentah.
const semua = $input.all();
const pasar = semua.map(i => i.json).find(j => Array.isArray(j.coins));
const koin = pasar && pasar.coins && pasar.coins[0];
const jam = new Date().toLocaleTimeString('id-ID', { timeZone: 'Asia/Jakarta', hour: '2-digit', minute: '2-digit' });

const baris = [
  'Otomasi selesai pada ' + jam + ' WIB.',
  '',
  '1. Satu catatan baru ditulis ke dasbor Reddie — buka tab "Pesan masuk" untuk melihatnya.',
  koin
    ? '2. Data pasar diambil langsung dari sumber luar: ' + koin.name + ' (' + koin.symbol + ') ' + (koin.change24h >= 0 ? 'naik ' : 'turun ') + Math.abs(koin.change24h).toFixed(1) + '% dalam 24 jam.'
    : '2. Data pasar diambil, tetapi sumbernya sedang tidak mengembalikan hasil.',
  '3. Ringkasan ini disusun n8n lalu dikirim balik ke Reddie.',
  '',
  'Tiga sistem berbeda bekerja dari satu klik, tanpa ada yang mengetik apa pun.'
];

return [{ json: { pesan: baris.join('\n') } }];
